<?php $b=$room['booking']; ?>
<div class="chat-shell" data-chat-room data-id="<?= $this->h($b['id']) ?>" data-poll="<?= $this->h($this->url('/api/v1/chat/poll')) ?>" data-send="<?= $this->h($this->url('/api/v1/chat/send')) ?>" data-csrf="<?= $this->h($this->csrf) ?>" data-now="<?= (int)$room['server_time'] ?>" data-start="<?= (int)$room['starts_at'] ?>" data-end="<?= (int)$room['ends_at'] ?>" data-can-send="<?= $room['can_send']?'1':'0' ?>">
<header class="chat-heading"><div><span class="eyebrow">گفت‌وگوی خصوصی مرشد</span><h1><?= $this->h($b['subject']) ?></h1><p><?= $this->h($b['mentor_name']) ?> · <?= $this->h($b['user_name']) ?></p></div><a class="secondary" href="<?= $this->h($this->url('/booking?id='.$b['id'])) ?>">جزئیات جلسه</a></header>
<div class="chat-state"><span data-chat-state role="status"><?= $this->h($room['reason']) ?></span><bdi data-chat-timer></bdi></div><p class="small muted">پیام‌ها در تاریخچهٔ خصوصی همین جلسه ذخیره می‌شوند. ورود به اتاق فقط برای دو شرکت‌کننده مجاز است؛ دسترسی موردی به آرشیو تابع مجوز رسیدگی است.</p>
<?php if($chatPolicy): ?><p class="small muted">پذیرش شما: <?= $chatPolicy['accepted']?'ثبت شده':'هنوز ثبت نشده' ?> · پذیرش طرف گفت‌وگو: <?= $chatPolicy['other_accepted']?'ثبت شده':'هنوز ثبت نشده' ?></p><?php endif; ?><?php if(!$chatPolicy): ?><p class="notice">شرایط نگهداری پیام‌های جلسه هنوز توسط مدیریت منتشر نشده است. ارسال پیام تا انتشار شرایط و پذیرش هر دو طرف بسته می‌ماند.</p><?php elseif(!$chatPolicy['accepted']): ?><details class="card chat-consent"><summary>خواندن و پذیرش شرایط نگهداری پیام‌ها</summary><h2><?= $this->h($chatPolicy['title']) ?></h2><div class="prose"><?= $this->paragraphs($chatPolicy['body']) ?></div><?= $this->start('/chat/consent') ?><input type="hidden" name="id" value="<?= $this->h($b['id']) ?>"><input type="hidden" name="version_id" value="<?= $this->h($chatPolicy['id']) ?>"><label><input type="checkbox" name="accepted" value="1" required>شرایط بالا را خواندم و برای حساب خودم می‌پذیرم.</label><button>ثبت پذیرش شرایط</button></form></details><?php endif; ?>
<button class="secondary chat-older" type="button" data-chat-older <?= $initial['more']?'':'hidden' ?>>پیام‌های قبلی</button><div class="chat-stream" data-chat-stream role="log" aria-label="پیام‌های جلسه" aria-live="polite" aria-relevant="additions"><?php foreach($initial['messages'] as $m): ?><article class="chat-bubble <?= $m['own']?'is-own':'' ?>" data-message-id="<?= (int)$m['id'] ?>"><span><?= $m['own']?'شما':'طرف گفت‌وگو' ?></span><p><?= $this->h($m['body']) ?></p><time data-timestamp="<?= (int)$m['created_at'] ?>"><?= $this->h(gmdate('H:i',(int)$m['created_at'])) ?></time></article><?php endforeach; ?></div><p class="chat-empty muted" data-chat-empty <?= $initial['messages']?'hidden':'' ?>>پیام‌های این جلسه اینجا نمایش داده می‌شوند.</p>
<form data-chat-form><label for="chat-body" class="small">پیام شما</label><div class="chat-compose"><textarea id="chat-body" name="body" maxlength="3000" rows="2" placeholder="پیامت را بنویس…" required <?= $room['can_send']?'':'disabled' ?>></textarea><button data-chat-submit <?= $room['can_send']?'':'disabled' ?>>ارسال پیام</button></div><p class="small muted" data-chat-send-status role="status">پیام تنها پس از ثبت در سرور ارسال‌شده محسوب می‌شود.</p></form><noscript><p class="notice">برای دریافت زندهٔ پیام‌ها، جاوااسکریپت مرورگر باید فعال باشد.</p></noscript></div>
